import{_ as i,C as n,o,c as a,E as s,a2 as r}from"./chunks/framework.Cm6XCzck.js";const d="/joinwell52/assets/figures/2026-08-28-skill-session-evidence-chain.en.svg",y=JSON.parse('{"title":"CodeFlowMu Engineering Record (II): Session Identity Cannot Be Self-Asserted — Building a Verifiable Execution-Evidence Boundary","description":"","frontmatter":{"title":"CodeFlowMu Engineering Record (II): Session Identity Cannot Be Self-Asserted — Building a Verifiable Execution-Evidence Boundary","date":"2026-08-28","updated":"2026-08-31","column":"digital-employee","category":"daily","article_type":"engineering-analysis","edition":"research-center","research_question":"When a skill invocation carries a session_id, how should the Runtime distinguish a caller claim, authoritative Session facts, and auditable execution evidence?","summary":"Historical CodeFlowMu skill journals exposed a deeper problem than a missing field: even when a session_id is present, it cannot become trusted execution evidence merely because the caller supplied it. V2.1.2 makes the Runtime verify ordinary skill calls against SessionStore across task, thread, session, agent and caller, with verified, sessionless/not_applicable and invalid_claim distinguishing trusted binding, legitimate no-session operation and unsupported identity claims.","sources":"/en/research/evidence/2026-08-28-skill-session-evidence","project_relevance":"substantive-relationship","item_id":"RBE-20260828-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-28-skill-session-evidence-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-08-28-skill-session-evidence.md","filePath":"en/digital-employee/2026-08-28-skill-session-evidence.md","lastUpdated":1788148073000}'),l={name:"en/digital-employee/2026-08-28-skill-session-evidence.md"};function c(h,e,u,p,g,m){const t=n("ArticleCover");return o(),a("div",null,[s(t,{image:"/assets/covers/daily-2026-08-28-skill-session-evidence-cover.png",kicker:"CodeFlowMu Engineering Record · 02",title:"Session Identity Cannot Be Self-Asserted — Building a Verifiable Execution-Evidence Boundary",summary:"Seeing a session_id in a log only proves that someone wrote that string. Turning it into execution evidence requires the Runtime to check its own authoritative Session facts.",version:"RBE-20260828-03",status:"Engineering Analysis · Revised 2026-08-31",languageHref:"/zh/digital-employee/2026-08-28-skill-session-evidence",languageLabel:"中文"}),e[0]||(e[0]=r('<h1 id="codeflowmu-engineering-record-ii-session-identity-cannot-be-self-asserted-—-building-a-verifiable-execution-evidence-boundary" tabindex="-1">CodeFlowMu Engineering Record (II): Session Identity Cannot Be Self-Asserted — Building a Verifiable Execution-Evidence Boundary <a class="header-anchor" href="#codeflowmu-engineering-record-ii-session-identity-cannot-be-self-asserted-—-building-a-verifiable-execution-evidence-boundary" aria-label="Permalink to &quot;CodeFlowMu Engineering Record (II): Session Identity Cannot Be Self-Asserted — Building a Verifiable Execution-Evidence Boundary&quot;">​</a></h1><p>A skill-invocation log can look complete: task identifier, skill name, <code>outcome=ok</code>, timestamp and even an integrity digest.</p><p>But one additional question can expose the evidence boundary immediately:</p><p><strong>Which real Agent Session did this invocation actually belong to?</strong></p><h2 id="what-is-codeflowmu-and-why-does-session-identity-become-core-evidence" tabindex="-1">What is CodeFlowMu, and why does Session identity become core evidence? <a class="header-anchor" href="#what-is-codeflowmu-and-why-does-session-identity-become-core-evidence" aria-label="Permalink to &quot;What is CodeFlowMu, and why does Session identity become core evidence?&quot;">​</a></h2><p>CodeFlowMu is a <strong>local-first multi-agent collaboration and digital-employee runtime</strong>. Different role agents execute work continuously inside controlled workspaces, while the Runtime maintains task objects, threads, Sessions, tool calls, Activity, recovery state and audit evidence.</p><p>In this kind of system, one TASK does not map to one model call. It may pass through first execution, crash recovery, rework, re-verification and handoff across different agents and different Sessions. <code>task_id</code> alone is therefore not enough to answer which concrete execution produced a particular action.</p><p>Session identity is not merely a chat-context label. It is a Runtime fact used to distinguish execution rounds, recovery boundaries and audit attribution.</p><p>The obvious implementation seems simple: let the caller include <code>session_id</code> and persist it in the journal.</p><p>That is still not enough.</p><p>A non-empty <code>session_id</code> is first a <strong>caller claim</strong>. It may refer to the correct Session, an ended Session, a Session for another task or Agent, or an identifier that the Runtime has never registered. If the system upgrades any non-empty string into a trusted binding, the audit record can become stronger than the underlying facts.</p><p>CodeFlowMu first encountered this as a Session-propagation gap in historical invocation records. The deeper design review then showed that the real problem was not merely a missing field. It was the absence of an <strong>authority boundary for execution identity</strong>.</p><p>V2.1.2 puts that boundary in the Runtime: a claimed Session identity is checked against SessionStore before the journal records <code>verified</code>, <code>sessionless/not_applicable</code>, or <code>invalid_claim</code> evidence semantics.</p><p>For the historical profile, version boundary and public evidence, see <a href="/joinwell52/en/research/evidence/2026-08-28-skill-session-evidence">RBE-20260828-03</a>.</p><h2 id="external-research-origin-configuration-existence-is-not-the-same-as-entering-the-current-session" tabindex="-1">External research origin: configuration existence is not the same as entering the current Session <a class="header-anchor" href="#external-research-origin-configuration-existence-is-not-the-same-as-entering-the-current-session" aria-label="Permalink to &quot;External research origin: configuration existence is not the same as entering the current Session&quot;">​</a></h2><p>The external comparison comes from <a href="https://github.com/OpenHands/OpenHands/pull/16971" target="_blank" rel="noreferrer">OpenHands PR #16971</a>, <code>fix(api): auto-load workspace hooks on conversation start</code>.</p><p>In the original 2026-08-28 research record it was still an open proposal, so this article preserves that historical status instead of rewriting it as an already-shipped OpenHands capability.</p><p>The proposal addressed a configuration-boundary problem: <code>.openhands/hooks.json</code> could exist in the workspace, yet Agent Canvas conversation startup did not automatically carry that configuration into the current conversation. The proposed path loaded hook configuration at conversation admission and made its presence observable through session state and actual <code>HookExecutionEvent</code> records.</p><p>The engineering lesson for us was broader than hooks:</p><p><strong>A resource can exist, enter a Session, be invoked, and produce a correct result — those are four different facts.</strong></p><p>OpenHands was dealing with an earlier boundary: <code>configuration exists → did it enter this conversation?</code></p><p>CodeFlowMu&#39;s issue sits later: <code>an invocation was observed → which authoritative Session owns this record?</code></p><p>They are adjacent problems, not the same bug and not the same implementation.</p><h2 id="historical-break-the-runtime-knew-the-session-but-persistent-evidence-lost-it" tabindex="-1">Historical break: the Runtime knew the Session, but persistent evidence lost it <a class="header-anchor" href="#historical-break-the-runtime-knew-the-session-but-persistent-evidence-lost-it" aria-label="Permalink to &quot;Historical break: the Runtime knew the Session, but persistent evidence lost it&quot;">​</a></h2><p>On the ordinary Playbook-reading path of CodeFlowMu V2.0.4 fixed commit <code>2ba1ad9b</code>, the Runtime already received agent, session, task and thread context. It could detect SDK tool reads of skill files and used <code>session_id + skill_id</code> for short-term deduplication.</p><p>But the final <code>recordSkillInvocation()</code> persistence path continued task and thread context while dropping Session identity from the journal.</p><p>The propagation break was therefore explicit:</p><p><code>Runtime knows Session → Session is used for short-term handling → persistent evidence loses Session attribution</code></p><p>A frozen historical sample through 2026-08-12 contained 59 invocation records:</p><table tabindex="0"><thead><tr><th>Correlation field</th><th style="text-align:right;">Present</th><th style="text-align:right;">Missing</th><th style="text-align:right;">Missing rate</th></tr></thead><tbody><tr><td><code>task_id</code></td><td style="text-align:right;">49</td><td style="text-align:right;">10</td><td style="text-align:right;">16.9%</td></tr><tr><td><code>session_id</code></td><td style="text-align:right;">0</td><td style="text-align:right;">59</td><td style="text-align:right;">100.0%</td></tr><tr><td><code>thread_key</code></td><td style="text-align:right;">42</td><td style="text-align:right;">17</td><td style="text-align:right;">28.8%</td></tr><tr><td><code>agent_id</code></td><td style="text-align:right;">15</td><td style="text-align:right;">44</td><td style="text-align:right;">74.6%</td></tr><tr><td><code>integrity</code></td><td style="text-align:right;">59</td><td style="text-align:right;">0</td><td style="text-align:right;">0%</td></tr></tbody></table><p>These 59 records are a frozen historical sample, not a statement about every version, every skill entry point or production frequency. They establish a narrower fact: <strong>the persisted records could have valid integrity fields while still being unable to reconstruct trusted Session attribution from the record alone.</strong></p><p>That distinction matters. Integrity does not prove identity truth.</p><p>A record can be provably unchanged since persistence while still containing an incorrect or unsupported identity claim. Integrity proves stability of the record; it does not prove the original identity was authoritative.</p><h2 id="a-counterexample-inside-the-same-system-the-goal-was-not-add-session-everywhere" tabindex="-1">A counterexample inside the same system: the goal was not “add session everywhere” <a class="header-anchor" href="#a-counterexample-inside-the-same-system-the-goal-was-not-add-session-everywhere" aria-label="Permalink to &quot;A counterexample inside the same system: the goal was not “add session everywhere”&quot;">​</a></h2><p>Not every CodeFlowMu skill-evidence path had the same evidence strength.</p><p>The same fixed version contained a stronger planning-evidence entry point, <code>pm.record_planning_skill_evidence</code>, that compared request context against Runtime-owned task, session, caller and thread facts before persisting planning evidence.</p><table tabindex="0"><thead><tr><th>Record type</th><th>What it could already prove</th><th>What it still could not prove</th></tr></thead><tbody><tr><td>Ordinary Skill / Playbook invocation record</td><td>A skill read was observed with partial task context</td><td>Trusted Session attribution could not be reconstructed</td></tr><tr><td>Formal planning-skill evidence</td><td>task/thread/session/caller were checked against Runtime authority</td><td>It still could not prove code, tests or final business results were correct</td></tr></tbody></table><p>So the engineering target could not honestly be stated as “the Skill Framework lacks Session support.”</p><p>The real target was:</p><p><strong>Give ordinary invocation evidence an explicit identity-source level instead of promoting caller-supplied fields directly into Runtime facts.</strong></p><p>That is the boundary between log collection and evidence engineering.</p><h2 id="why-persisting-session-id-verbatim-can-create-false-evidence" tabindex="-1">Why persisting <code>session_id</code> verbatim can create false evidence <a class="header-anchor" href="#why-persisting-session-id-verbatim-can-create-false-evidence" aria-label="Permalink to &quot;Why persisting `session_id` verbatim can create false evidence&quot;">​</a></h2><p>Suppose a request carries:</p><p><code>session_id = session-042</code></p><p>The system still needs to know at least:</p><ol><li>whether <code>session-042</code> exists in the current Runtime SessionStore;</li><li>whether it belongs to the current <code>task_id</code>;</li><li>whether it belongs to the current <code>thread_key</code>;</li><li>whether the recorded Agent matches the invoking Agent;</li><li>whether the current caller may attribute the action to that Session, and whether the Session state is acceptable.</li></ol><p>If none of those are checked, a string that merely looks like a Session ID can be persisted as if it were a verified binding. EVAL, recovery logic, audit panels and ADMIN views would then consume <strong>system-packaged false strong evidence</strong> rather than weak evidence.</p><p>That is more dangerous than a missing field. A blank field tells downstream consumers “we do not know.” An unverified value presented as trusted tells them “the Runtime knows which execution this was,” even when it does not.</p><p>V2.1.2 therefore follows a simple rule:</p><blockquote><p><strong>A claim may be recorded, but only a claim the Runtime itself can verify may become an execution-identity fact.</strong></p></blockquote><h2 id="v2-1-2-session-identity-returns-to-runtime-authority" tabindex="-1">V2.1.2: Session identity returns to Runtime authority <a class="header-anchor" href="#v2-1-2-session-identity-returns-to-runtime-authority" aria-label="Permalink to &quot;V2.1.2: Session identity returns to Runtime authority&quot;">​</a></h2><p>V2.1.2 no longer treats a caller-supplied <code>session_id</code> as trusted execution evidence. The Runtime reads SessionStore and checks the available context across:</p><ul><li><code>task_id</code>;</li><li><code>thread_key</code>;</li><li><code>session_id</code>;</li><li>agent;</li><li>caller;</li><li>Session existence and acceptable state.</li></ul><p>The journal now records explicit evidence semantics rather than a vague “has Session / no Session” split:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Persisted semantics</th><th>Audit meaning</th></tr></thead><tbody><tr><td>SessionStore record exists and identity/context match</td><td><code>session_binding=verified</code></td><td>Runtime-authoritative Session facts support this invocation attribution</td></tr><tr><td>The operation is legitimately sessionless by design and Runtime records the reason</td><td><code>sessionless/not_applicable</code></td><td>No Session is a valid semantic state rather than an omitted field</td></tr><tr><td>Session is unregistered, state is unacceptable, or agent/caller/task/thread disagree</td><td><code>session_binding=invalid_claim</code></td><td>Preserve an unsupported claim as negative audit evidence; do not promote it to verified identity</td></tr></tbody></table><p>These states separate three situations that used to be easy to conflate:</p><p><strong>binding really succeeded; the operation legitimately needs no Session; someone claimed a binding the Runtime cannot support.</strong></p><p><code>invalid_claim</code> must not be silently erased.</p><p>If the Runtime simply converts an invalid Session claim into <code>session_id=null</code>, later auditing can see only “no Session” and loses the fact that someone actually claimed a specific Session and failed verification. V2.1.2 therefore preserves the invalid claim as a negative fact.</p><p>Negative evidence is still evidence.</p><h2 id="why-invalid-claim-must-not-be-auto-corrected" tabindex="-1">Why <code>invalid_claim</code> must not be auto-corrected <a class="header-anchor" href="#why-invalid-claim-must-not-be-auto-corrected" aria-label="Permalink to &quot;Why `invalid_claim` must not be auto-corrected&quot;">​</a></h2><p>Agent systems create a strong temptation to “helpfully” repair identity. If a caller supplies the wrong Session and the Runtime can guess which one it probably meant, why not rewrite it?</p><p>For execution evidence, that would be dangerous.</p><p>The moment the system replaces an unsupported identity with “the most likely one,” it stops being a fact recorder and becomes an identity inference engine. The audit chain then loses the distinction between the original claim, the authoritative fact and whether they actually matched.</p><p>The safer sequence is:</p><p><code>claim → authority verification → evidence state</code></p><p>not:</p><p><code>claim → best guess → pretend verified</code></p><p>If a later workflow needs recovery, rebinding or human correction, that should create a new, separately traceable governance action rather than rewriting the meaning of historical invocation evidence.</p><h2 id="task-thread-session-agent-and-caller-are-not-interchangeable" tabindex="-1">task, thread, session, agent and caller are not interchangeable <a class="header-anchor" href="#task-thread-session-agent-and-caller-are-not-interchangeable" aria-label="Permalink to &quot;task, thread, session, agent and caller are not interchangeable&quot;">​</a></h2><p>These identity keys answer different questions:</p><table tabindex="0"><thead><tr><th>Identity key</th><th>Question answered</th></tr></thead><tbody><tr><td><code>task_id</code></td><td>Which business task did this execution serve?</td></tr><tr><td><code>thread_key</code></td><td>Which collaboration or causal chain contained it?</td></tr><tr><td><code>session_id</code></td><td>Which concrete execution Session did it belong to?</td></tr><tr><td>agent</td><td>Which execution role / Agent performed the action?</td></tr><tr><td>caller</td><td>Who initiated this invocation?</td></tr></tbody></table><p>One task can pass through initial execution, crash recovery, rework and re-verification across several Sessions. One thread can span several roles and task phases.</p><p><code>task_id</code> cannot prove Session identity. <code>thread_key</code> cannot prove Session identity either. And a self-asserted Session cannot override contradictions in task, thread, agent or caller.</p><p>The V2.1.2 boundary puts these dimensions back under one Runtime authority check.</p><h2 id="identity-truth-and-record-integrity-are-different-proofs" tabindex="-1">Identity truth and record integrity are different proofs <a class="header-anchor" href="#identity-truth-and-record-integrity-are-different-proofs" aria-label="Permalink to &quot;Identity truth and record integrity are different proofs&quot;">​</a></h2><p>The invocation journal already had integrity mechanisms; Session engineering does not replace them.</p><ul><li><strong>SessionStore verification</strong> asks whether the identity claim matches Runtime-authoritative Session facts.</li><li><strong>journal integrity verification</strong> asks whether the persisted record remains verifiably unchanged.</li></ul><p>An invalid Session claim with a valid integrity digest is still only “an incorrect claim preserved intact.” Conversely, a previously <code>verified</code> record that is later altered still needs integrity verification to detect tampering.</p><p>The two proofs cannot substitute for one another.</p><p>That is a key difference between evidence systems and ordinary logs: <strong>more fields do not automatically mean stronger evidence; the authority source of each field matters.</strong></p><p><img src="'+d+'" alt="Four different facts behind “the skill is active”"></p><p><em>Figure 1. Configuration existence, Session loading, invocation, and result verification are separate evidence layers. V2.1.2 adds Runtime-verified persistent Session attribution for ordinary invocations; it does not replace result verification. Source: <a href="/joinwell52/en/research/evidence/2026-08-28-skill-session-evidence">RBE-20260828-03</a>.</em></p><h2 id="independent-qa-verify-one-real-sessionstore-binding-chain" tabindex="-1">Independent QA: verify one real SessionStore binding chain <a class="header-anchor" href="#independent-qa-verify-one-real-sessionstore-binding-chain" aria-label="Permalink to &quot;Independent QA: verify one real SessionStore binding chain&quot;">​</a></h2><p>Independent QA did not merely check whether a new <code>session_id</code> field appeared in the journal.</p><p>C1 first created a real SessionStore registration, invoked the ordinary skill-read path, then read the persistent journal and checked identity plus integrity.</p><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>Corresponding Session exists in SessionStore</td><td>found</td></tr><tr><td>Persisted journal records for the call</td><td>1</td></tr><tr><td>task / thread / session</td><td>3/3 matched expected input</td></tr><tr><td>agent / caller</td><td>matched expectation</td></tr><tr><td><code>session_binding</code></td><td><code>verified</code></td></tr><tr><td><code>binding_reason</code></td><td><code>runtime_session_store_match</code></td></tr><tr><td><code>evidence_source</code></td><td><code>sdk_tool_call</code></td></tr><tr><td>integrity verification</td><td>passed</td></tr></tbody></table><p>The evidence boundary still matters. C1 proves a complete positive binding chain for one real valid Session. Forged/unregistered Session, legitimate sessionless behavior, cross-Session distinction and same-Session deduplication are covered by targeted failure/boundary tests; one C1 case cannot independently stand in for every branch.</p><p>The historical 59 records without Session identity are not automatically upgraded to <code>verified</code> because a new version was released. If there is no reliable source from which to recover an old identity, it remains unknown. Refusing to guess historical identity is itself part of evidence discipline.</p><h2 id="verified-proves-execution-attribution-not-correctness-of-the-work" tabindex="-1"><code>verified</code> proves execution attribution, not correctness of the work <a class="header-anchor" href="#verified-proves-execution-attribution-not-correctness-of-the-work" aria-label="Permalink to &quot;`verified` proves execution attribution, not correctness of the work&quot;">​</a></h2><p>Suppose a journal record has the correct task, thread, Session and Agent/caller, plus <code>session_binding=verified</code> and <code>outcome=ok</code>.</p><p>What it proves is narrower:</p><p><strong>The Runtime has evidence that this skill invocation occurred under that verified identity combination and that the invocation itself completed according to the interface semantics.</strong></p><p>It still does not prove:</p><ul><li>the skill advice was correct;</li><li>the Agent fully followed the skill;</li><li>the code change was correct;</li><li>test coverage was sufficient;</li><li>a REPORT conclusion was valid;</li><li>QA should PASS;</li><li>PM or ADMIN should approve.</li></ul><p>A more complete evidence ladder remains:</p><p><code>available → recommended/bound → invoked → identity_verified → result_verified</code></p><p>The last layer still requires code diff, tool output, runtime artifacts, tests, REPORT, REVIEW, EVAL and QA/PM governance evidence.</p><p>V2.1.2 strengthens <strong>truth of invocation attribution</strong>. It does not give the Runtime business-adjudication authority.</p><h2 id="what-this-means-for-a-digital-employee-runtime" tabindex="-1">What this means for a digital-employee runtime <a class="header-anchor" href="#what-this-means-for-a-digital-employee-runtime" aria-label="Permalink to &quot;What this means for a digital-employee runtime&quot;">​</a></h2><p>Session identity may look like a small logging field, but in a long-running digital-employee system it determines whether later automation can be trusted:</p><ul><li>after a crash, can recovery distinguish a call from the old Session and one from the new recovery Session?</li><li>during EVAL review, can a behavior be attributed to the correct execution round?</li><li>in multi-agent work, can actions on the same task be separated by Agent and Session?</li><li>when ADMIN reviews evidence, will a caller claim be falsely presented as “Runtime verified”?</li><li>can later diagnostics or monitoring reason from verified execution identity rather than guessing from timestamps?</li></ul><p>If Session is merely an optional string, increasing automation also increases the cost of misattribution.</p><p>The principle established here is therefore broader than “better logging”:</p><p><strong>Execution identity belongs to Runtime authority, not to caller self-assertion.</strong></p><h2 id="from-engineering-patch-to-formal-version" tabindex="-1">From engineering patch to formal version <a class="header-anchor" href="#from-engineering-patch-to-formal-version" aria-label="Permalink to &quot;From engineering patch to formal version&quot;">​</a></h2><p>CodeFlowMu V2.1.2 was released on August 30, 2026. Its Runtime and Shell source code is maintained in a private repository. Session identity verification shipped together with persistent task idempotency and Activity safe projection as one Runtime boundary-safety patch.</p><p>Public articles do not point readers to inaccessible private CodeFlowMu repository links. Publicly reviewable version facts, sanitized C1 results, compatibility and residual risks are available in the <a href="/joinwell52/en/research/evidence/2026-08-28-skill-session-evidence">public evidence pack</a> and the <a href="/joinwell52/en/research/evidence/2026-08-30-codeflowmu-v2.1.2-public-release-summary">V2.1.2 Public Release Summary</a>.</p><p>Final release validation recorded:</p><ul><li>Runtime: <strong>1842 pass / 0 fail / 1 skip</strong>;</li><li>Shell: <strong>1037 pass / 0 fail / 0 skip</strong>;</li><li>V2.1.1 and V2.1.2 same-protocol critical scenarios, ten consecutive rounds each: Runtime <strong>1630/1630</strong>, Shell <strong>550/550</strong>;</li><li>typecheck, Shell build, installer contract, rules and version consistency passed.</li></ul><p>These numbers describe the overall V2.1.2 release test set. They are not a “Session evidence trust rate,” and they do not prove coverage of every Host, real LAN/Gateway deployment, browser profile or user production project.</p><p>The release covers the CodeFlowMu Runtime and Shell maintained in a private repository. It does not include an independent Open Dev Team Edition, and it requires no migration of existing TASK, REPORT, Session or Activity files.</p><h2 id="a-review-checklist-for-other-agent-runtimes" tabindex="-1">A review checklist for other Agent Runtimes <a class="header-anchor" href="#a-review-checklist-for-other-agent-runtimes" aria-label="Permalink to &quot;A review checklist for other Agent Runtimes&quot;">​</a></h2><p>When an Agent system records Skill, Tool, Hook or MCP invocations, ask:</p><ol><li>Is <code>session_id</code> caller-supplied, or derived from an authoritative Runtime registration?</li><li>Is Session checked together with task, thread, agent, caller and state?</li><li>Are “legitimately no Session” and “incorrect Session claim” represented differently?</li><li>Is an invalid claim preserved as negative audit evidence instead of being silently deleted or guessed into a replacement?</li><li>Are identity verification and log integrity treated as distinct proofs?</li><li>Do task/thread/session keep separate semantics rather than substituting for each other?</li><li>Do UI, EVAL and recovery logic treat only <code>verified</code> as verified attribution?</li><li>Is invocation success still separated from engineering-result and business-result validation?</li><li>Do historical records with missing identity remain unknown rather than being inferred for cosmetic completeness?</li></ol><p>These questions reveal much more about trustworthy execution evidence than “does the log have a Session field?”</p><h2 id="engineering-conclusion" tabindex="-1">Engineering conclusion <a class="header-anchor" href="#engineering-conclusion" aria-label="Permalink to &quot;Engineering conclusion&quot;">​</a></h2><p>The most important change in this CodeFlowMu engineering record is not that the skill journal gained another ID.</p><p>It is the establishment of three evidence levels:</p><p><strong>The caller may make an identity claim. The Runtime verifies it. Only a verified identity may become trusted execution evidence.</strong></p><p>Legitimate sessionless operations need their own semantics. Unsupported claims must remain visible as negative facts. Only then can recovery, EVAL, auditing and governance build on verifiable identity rather than on a field that merely looks plausible.</p><p>For a digital-employee runtime, Session is not contextual decoration and not a label the caller can define by fiat.</p><p>It is the evidence boundary for answering:</p><p><strong>Which real execution did this action actually belong to?</strong></p><h2 id="evidence-scope-and-primary-sources" tabindex="-1">Evidence scope and primary sources <a class="header-anchor" href="#evidence-scope-and-primary-sources" aria-label="Permalink to &quot;Evidence scope and primary sources&quot;">​</a></h2><ul><li><a href="/joinwell52/en/research/evidence/2026-08-28-skill-session-evidence">Historical profile, mixed evidence sample, V2.1.2 engineering update and public release evidence</a>: historical fixture, Reader and check validate frozen material; the public page also maps sanitized implementation facts, C1 independent QA, release gates and residual risks.</li><li><a href="https://github.com/OpenHands/OpenHands/pull/16971" target="_blank" rel="noreferrer">OpenHands PR #16971</a>: recorded in the 2026-08-28 research as an open proposal; it provides the adjacent problem model of configuration entering a Session, not CodeFlowMu source code or delivery proof.</li><li>CodeFlowMu V2.1.2 implementation, independent-QA and raw release logs remain in the private repository; this public article does not expose inaccessible private links as reader-facing evidence.</li><li>This article does not prove that skill advice was correct, that an Agent fully followed a skill, that invocation evidence replaces result acceptance, or that historical Session identities can be safely inferred and backfilled.</li></ul>',126))])}const f=i(l,[["render",c]]);export{y as __pageData,f as default};
